import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mul, vec2 } from 'three/tsl';

export default async function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create plane geometry matching atlas region aspect ratio (512x320 = 1.6:1)
  const geometry = new THREE.PlaneGeometry(1.6, 1, 1, 1);

  // Load the texture
  const texture = await ctx.textureLoader.loadTexture(config.imageUrl);
  texture.flipY = false;

  // UV offset for atlas region (0,0,512,320 in a typical atlas)
  // Assuming full atlas is 512×320 and this region occupies it fully
  const uvNode = mul(uv(), vec2(1, 1)); // Full region occupies the texture
  const colorNode = texture;

  // Create material with tsl nodes
  const material = new MeshBasicNodeMaterial({
    colorNode,
    transparent: true,
    depthWrite: false,
    side: THREE.DoubleSide,
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(config.scenePosition?.[0] ?? -3.2, config.scenePosition?.[1] ?? -0.3, config.scenePosition?.[2] ?? 0);

  // Billboard effect: always face camera
  mesh.userData.handlers = {};
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  return mesh;
}
